fn vec_len<T>(x: &Vec<T>) -> usize {
    x.len()
}

fn numpy_log10(x: Vec<f32>) -> Vec<f32> {
    // Preallocate the result vector to exactly the input length
    let mut result = Vec::with_capacity(x.len());
    // For each element in the input, compute log10 and push into result
    for v in x {
        result.push(v.log10());
    }
    result
}

